'use strict';

const _cloneDeep = require('lodash/cloneDeep');
const _get = require('lodash/get');
const Mustache = require('mustache');
const stringify = require('../stringify');

const defaultConfig = {
    template: '{{date}} {{levelName}}: {{msg}}',
    resolvers: {
        date: record => record.date.toISOString(),
    },
};

/**
 * Стрим для yandex-logger, позволяющий писать в stdout отформатированную строку лога.
 *
 * Парсинг шаблонов производится через Mustache.Render
 * Дальше создается конвейер функций, принимающих record и возвращающих значение
 * Функция рендера, проходит по конвейеру и последовательно вызывает эти функции
 *
 * @param {YandexLoggerLineStreamConfig} [config]
 * @returns {Writable}
 */
module.exports = config => {
    config = Object.assign({}, defaultConfig, config);
    let template = config.template;
    let resolvers = config.resolvers;
    let stream = config.stream || process.stdout;

    template += '\n';
    let renderer = createRenderer(template, resolvers);

    return {
        /**
         * @param {Object} record
         * @returns {undefined}
         */
        write(record) {
            let output = renderer(record);

            stream.write(output);
        },
    };
};

function createRenderer(template, resolvers) {
    let tokens = parse(template, resolvers);
    return record => render(record, tokens);
}

/**
 * Пасринг шаблона и создание конвейера функций
 * Используется алгоритм сортировочных станций
 * @param {String} template
 * @param {Object<String, Function>} resolvers
 * @returns {Array} Возвращает токены [type, name, lambda]
 */
function parse(template, resolvers) {
    resolvers = Object.assign({}, resolvers);
    let inputTokens = _cloneDeep(Mustache.parse(template));
    inputTokens.reverse();

    let tokens = [];
    let subTokens = [];

    while (inputTokens.length > 0) {
        let input = inputTokens.pop();
        let type = input[0];

        // Встретили условный оператор, начинаем накапливать значения
        if (type === '#' && input[4].length > 0) {
            pushConditionToken(input);
            continue;
        }

        let token;
        if (type === '/') {
            token = extractConditionToken(input[1]);
        } else if (type === 'name') {
            token = getParamToken(input);
        } else {
            token = getTextToken(input);
        }

        pushToken(token);
    }

    function pushConditionToken(token) {
        let index = subTokens.push(['#', token[1]]) - 1;

        // Токены нужно перевернуть, так как у нас стек
        token[4].reverse();

        // Помещаем во входящий стек токенов маркер для захвата значений, попавших под условие
        // Сохраняем индекс для упрощения доставания токенов из subTokens
        inputTokens = inputTokens.concat([['/', index]], token[4]);
    }

    function extractConditionToken(index) {
        // Токены нужны в порядке помещения их в subTokens
        let tokens = subTokens.splice(index + 1);
        let token = subTokens.pop();

        // нужен другой токен, чтобы на него не заматчится
        return ['&#', token[1], conditionResolver(token[1], tokens)];
    }

    function getParamToken(token) {
        let name = token[1];
        return ['&', name,
            (name in resolvers) ?
                resolvers[name] :
                record => defaultResolver(record, name)];
    }

    function getTextToken(token) {
        // Другие токены потеряют обвязку, вставится только их имя
        return ['=', token[1], () => token[1]];
    }

    function pushToken(value) {
        // Непустой subTokens признак того, что значения попадают под условный опертор
        if (subTokens.length > 0) {
            subTokens.push(value);
        } else {
            tokens.push(value);
        }
    }

    // На выходе массив резолверов
    return tokens;
}

function render(record, tokens) {
    return tokens.map(item => item[2](record)).join('');
}

function defaultResolver(record, fieldName) {
    let value = _get(record, fieldName);
    return typeof value === 'object' ?
        stringify(value) :
        value;
}

function conditionResolver(fieldName, tokens) {
    return record => {
        let value = _get(record, fieldName);
        return value ?
            render(record, tokens) :
            '';
    };
}

/**
 * @typedef {Object} YandexLoggerLineStreamConfig
 * @property {String} [stream] - Writable stream, например, process.stdout
 * @property {String} [template]
 * @property {Object<String, Function>} [resolvers]
 */
